import{m as w}from"./main-C2EWBUK7.js";import{Ar as te,Cn as hn}from"./chunk-ndNoG5v4.js";var l="Coach Hajaro";var o=(i,t)=>({type:`h2`,id:i,text:t});var b=(i,t)=>({type:`h3`,id:i,text:t});var e=i=>({type:`p`,text:i});var s=(...i)=>({type:`ul`,items:i});var d=(...i)=>({type:`ol`,items:i});var c=i=>({type:`callout`,text:i});var a=(i,t)=>({type:`link`,text:i,href:t});var y=[{id:`progressive-overload-guide`,slug:`progressive-overload-guide`,title:"Progressieve overload: het principe achter elk goed schema",seoTitle:"Progressieve overload uitgelegd: zo blijf je groeien",metaDescription:"Lees wat progressieve overload is, hoe je het toepast, en een eenvoudig systeem met dubbele progressie om spieren en kracht te blijven opbouwen.",excerpt:"Spieren passen zich aan aan wat je van ze vraagt. Met progressieve overload vraag je steeds een beetje meer. Zo pas je het toe zonder op te branden.",category:`muscle-growth`,author:l,publishedAt:`2026-03-02`,updatedAt:`2026-09-18`,readingMinutes:7,tags:["progressieve overload",`hypertrophy`,`programming`],featured:!0,published:!0,body:[e("Als één principe trainen onderscheidt van gewoon bewegen, dan is het progressieve overload: wat je van je spieren vraagt langzaam opvoeren, zodat ze een reden hebben om zich te blijven aanpassen."),o(`what-is-progressive-overload`,"Wat progressieve overload echt betekent"),e("Je lichaam past zich aan aan de belasting die je het geeft. Voelt een gewicht licht voor hetzelfde aantal herhalingen, dan is het geen nieuwe uitdaging meer en vertraagt je vooruitgang. Overload betekent net iets meer doen dan eerst. Niet elke training, maar gestaag over weken en maanden."),o(`ways-to-progress`,"Manieren om vooruit te gaan"),s("Gewicht: meer tillen voor hetzelfde aantal herhalingen.","Herhalingen: meer herhalingen doen met hetzelfde gewicht.","Sets: sets toevoegen, voorzichtig en binnen wat je kunt herstellen.","Bewegingsuitslag en controle: hetzelfde werk doen met een grotere beweging, of het gewicht langzamer laten zakken."),c("Gewicht toevoegen terwijl je techniek slechter wordt, is geen progressieve overload. Het is een andere, makkelijkere oefening die je slecht uitvoert."),o(`double-progression`,"Een eenvoudig systeem: dubbele progressie"),e("Dubbele progressie is voor de meeste sporters de eenvoudigste betrouwbare methode. Kies een herhalingsrange, bijvoorbeeld 8 tot 12 herhalingen."),d("Begin met een gewicht dat je 8 keer kunt tillen, met nog 1 tot 3 herhalingen over.","Probeer elke training in een of meer sets een herhaling extra te doen.","Haal je in elke set 12 herhalingen met goede techniek, voeg dan de kleinste gewichtsstap toe die er is.","Ga met het nieuwe gewicht terug naar ongeveer 8 herhalingen en herhaal."),b(`track-everything`,"Houd alles bij"),e("Vooruitgang die je niet opschrijft, kun je niet sturen. Houd je sets, herhalingen en gewichten bij. De trainingsplanner op deze site is daar precies voor gemaakt."),a("Open de trainingsplanner",`/workout-planner`),o(`when-progress-stalls`,"Als je vastloopt"),e("Vastlopen is normaal. Controleer eerst de basis voordat je je schema verandert: slaap, totale calorieën, eiwit en stress. Zit dat goed en loop je al twee of drie weken vast, probeer dan een deloadweek of een kleine wijziging in je oefeningen."),a("Bekijk de trainingsschema's",`/programs`)]},{id:`protein-intake-for-muscle-growth`,slug:`protein-intake-for-muscle-growth`,title:"Hoeveel eiwit heb je nodig om spieren op te bouwen?",seoTitle:"Eiwit voor spiergroei: hoeveel heb je nodig?",metaDescription:"Wat onderzoek zegt over eiwit voor spieropbouw, hoe je het over de dag verdeelt, en praktische eiwitrijke voeding.",excerpt:"Eiwit is de bouwstof van spieren. Zo veel heb je nodig, zo verdeel je het over je dag en zo haal je je doel met gewoon eten.",category:`nutrition`,author:l,publishedAt:`2026-04-11`,updatedAt:`2026-08-30`,readingMinutes:6,tags:[`protein`,`nutrition`,"spiergroei"],featured:!0,published:!0,body:[e("Training geeft je spieren een reden om te groeien; eiwit is het materiaal waarmee ze groeien. Zonder genoeg eiwit levert je werk in de sportschool minder op dan het zou kunnen."),o(`how-much`,"Hoeveel eiwit per dag?"),e("Voor de meeste mensen die krachttraining doen en spieren willen opbouwen, ondersteunt onderzoek ongeveer 1,6 tot 2,2 g eiwit per kilo lichaamsgewicht per dag. Tijdens een vetverliesfase helpt het om naar de bovenkant te mikken, zodat je je spieren behoudt."),c("Voorbeeld: iemand van 80 kg mikt op ongeveer 130 tot 175 g eiwit per dag."),o(`distribution`,"Verdeel het over de dag"),e("Eiwit verdelen over drie tot vijf maaltijden, elk met ongeveer 0,3 tot 0,5 g per kg lichaamsgewicht, is een praktische manier om je doel te halen en de spieropbouw de hele dag te ondersteunen."),o(`food-sources`,"Goede eiwitbronnen"),s("Mager vlees en gevogelte: kip, kalkoen, mager rundvlees","Vis en zeevruchten: zalm, tonijn, witvis, garnalen","Eieren en zuivel: Griekse yoghurt, skyr, hüttenkäse, melk","Plantaardig: tofu, tempé, linzen, bonen, edamame en mixen van plantaardige eiwitten","Eiwitpoeder: handig als je met gewoon eten tekortkomt"),o(`special-cases`,"Over je gezondheid"),e("Heb je een nierziekte of een andere aandoening, overleg dan met je arts of een diëtist voordat je meer eiwit gaat eten."),a("Bereken je dagelijkse eiwitdoel",`/nutrition/calculators`)]},{id:`squat-technique-guide`,slug:`squat-technique-guide`,title:"Squattechniek: veilig squatten, stap voor stap",seoTitle:"Zo squat je goed: techniek van de back squat stap voor stap",metaDescription:"Leer de back squat: opstelling stap voor stap, aandachtspunten voor de beweging, veelgemaakte fouten en hoe je de juiste diepte voor jouw lichaam vindt.",excerpt:"Goed uitgevoerd bouwt de squat meer spiermassa en kracht in je onderlichaam op dan bijna elke andere oefening. Zo stel je je op, voer je hem uit en ga je vooruit.",category:`exercise-technique`,author:l,publishedAt:`2026-05-06`,updatedAt:`2026-05-06`,readingMinutes:8,tags:[`squat`,`technique`,`legs`],published:!0,body:[e("De back squat met halterstang traint je quadriceps, billen en adductoren, en vraagt veel van je romp en bovenrug. Met een goede techniek kun je hem jarenlang zwaar en veilig belasten."),o(`setup`,"Opstelling"),d("Zet de stang op halve borsthoogte in een rek, met de veiligheidsstangen net onder je laagste punt.","Stap onder de stang en leg hem op je bovenrug, op de spieren en niet op je nek.","Pak de stang net buiten je schouders en trek je ellebogen omlaag om je bovenrug aan te spannen.","Kom omhoog om de stang uit het rek te halen, doe twee of drie stappen achteruit en zet je voeten ongeveer op schouderbreedte, tenen iets naar buiten."),o(`execution`,"Uitvoering"),d("Adem diep in naar je buik en zijkanten en span je romp aan alsof je een stoot gaat opvangen.","Zak tussen je heupen naar beneden en laat je knieën naar voren gaan, in lijn met je tenen.","Zak zo diep als je kunt beheersen, met een neutrale rug en je hielen op de grond.","Duw jezelf omhoog met je hele voet, houd je borst omhoog en je romp gespannen."),o(`depth`,"Hoe diep moet je squatten?"),e("Squat zo diep als je kunt met een neutrale onderrug en je hele voet op de grond. Voor de meeste mensen is dat op of onder parallel. Diepere squats trainen je quadriceps en billen over een grotere beweging, en dat helpt spiergroei."),o(`common-mistakes`,"Veelgemaakte fouten"),s("Knieën die naar binnen vallen: denk eraan de grond met je voeten uit elkaar te duwen.","Hielen die loskomen: werk aan je enkelmobiliteit, of leg voorlopig iets onder je hielen.","Spanning verliezen onderin: neem minder gewicht en oefen met een pauze onderin.","Heupen die als eerste omhoog schieten (een 'good-morning squat'): ga langzamer en leid met je borst."),a("Bekijk de back squat in de oefeningenbibliotheek",`/exercises/barbell-back-squat`),a("Bekijk de beenspieren op de spierkaart",`/muscle-chart?muscle=quadriceps`)]},{id:`sustainable-fat-loss`,slug:`sustainable-fat-loss`,title:"Vet verliezen zonder spieren te verliezen",seoTitle:"Vet verliezen zonder spierverlies: een praktische gids",metaDescription:"Zo stel je een calorietekort in dat je volhoudt, blijf je zwaar trainen en gebruik je eiwit en cardio slim om vet te verliezen.",excerpt:"Vetverlies is simpel op papier en lastig in de praktijk. Dit zijn de dingen die ertoe doen, en zo gebruik je ze zonder spieren te verliezen.",category:`fat-loss`,author:l,publishedAt:`2026-06-14`,updatedAt:`2026-10-02`,readingMinutes:7,tags:["vetverlies","calorietekort",`cutting`],featured:!0,published:!0,body:[e("Vet verliezen vraagt een calorietekort: minder energie binnenkrijgen dan je verbruikt. Je spieren behouden terwijl je dat doet, vraagt meer: hard blijven trainen, genoeg eiwit en een tekort dat niet te groot is."),o(`the-deficit`,"Kies een gematigd tekort"),e("Ongeveer 0,5 tot 1% van je lichaamsgewicht per week verliezen is voor de meeste mensen een verstandig doel. Sneller gaan vergroot de kans op spierverlies, honger en vermoeidheid, en is moeilijker vol te houden."),o(`keep-training-heavy`,"Blijf zwaar trainen"),e("Krachttraining is het signaal dat je lichaam vertelt zijn spieren te houden. Blijf dezelfde gewichten tillen, ook als je later in het dieet iets minder sets doet."),o(`protein`,"Eet genoeg eiwit"),e("In een tekort heb je meer eiwit nodig. Mikken op ongeveer 1,8 tot 2,2 g per kg lichaamsgewicht helpt je spieren te behouden en geeft een voller gevoel tussen de maaltijden."),o(`cardio`,"Gebruik cardio als hulpmiddel"),s("Dagelijkse stappen zijn een onderschatte manier om meer energie te verbruiken zonder moe te worden.","Rustige cardio zoals wandelen op een helling herstel je makkelijk van.","Zware intervallen werken, maar maken je moe, dus gebruik ze met mate."),o(`track-trends`,"Kijk naar het verloop, niet naar één weging"),e("Je gewicht schommelt elke dag door vocht, hoeveel eten je binnen hebt en zout. Weeg jezelf onder dezelfde omstandigheden en vergelijk weekgemiddelden, samen met metingen en foto's."),c("Volg een zeer caloriearm dieet alleen onder medisch toezicht."),a("Schat je dagelijkse caloriebehoefte",`/nutrition/calculators`),a("Bekijk het schema Vetverlies & definitie",`/programs/fat-loss-and-definition`)]},{id:`sleep-and-recovery-for-lifters`,slug:`sleep-and-recovery-for-lifters`,title:"Slaap en herstel: waar spieren gebouwd worden",seoTitle:"Slaap en herstel voor spiergroei: gids voor krachtsporters",metaDescription:"Waarom slaap en herstel belangrijk zijn voor spiergroei en kracht, en praktische gewoontes om beter te herstellen tussen trainingen.",excerpt:"Training put je spieren uit; tijdens herstel komen ze sterker terug. Deze gewoontes helpen je sneller te herstellen en harder te trainen.",category:`recovery`,author:l,publishedAt:`2026-07-20`,updatedAt:`2026-07-20`,readingMinutes:5,tags:[`sleep`,`recovery`,`deload`],published:!0,body:[e("Training is de reden dat spieren groeien, maar het groeien zelf gebeurt terwijl je herstelt. Slecht herstel beperkt hoe hard je kunt trainen en hoe goed je lichaam reageert."),o(`sleep`,"Slaap gaat voor"),e("De meeste volwassenen functioneren het best met 7 tot 9 uur slaap per nacht. Te weinig slaap gaat samen met slechtere prestaties, meer honger en minder goed herstel."),s("Ga op vaste tijden naar bed en sta op vaste tijden op, ook in het weekend.","Maak je slaapkamer donker, stil en koel.","Beperk cafeïne in de 8 uur voor het slapengaan.","Kom tot rust zonder felle schermen in het laatste halfuur tot uur."),o(`deloads`,"Plan deloads"),e("Een deload is een geplande week met minder sets of lichtere gewichten. Neem er een om de 6 tot 8 weken, of als je prestaties, slaap en motivatie alle drie dalen. Dan kan de vermoeidheid wegtrekken en blijf je vooruitgaan."),o(`active-recovery`,"Actief herstel"),e("Licht wandelen, mobiliteitsoefeningen en rustig fietsen brengen je bloed op gang zonder je moe te maken. Ideaal voor rustdagen."),a("Lees meer over voeding en herstel",`/nutrition`)]},{id:`creatine-evidence-guide`,slug:`creatine-evidence-guide`,title:"Creatine: wat het onderzoek zegt",seoTitle:"Creatine monohydraat: effecten, dosering en onderzoek",metaDescription:"Wat onderzoek zegt over creatine monohydraat: wat het doet, de gebruikelijke dosis, wie er baat bij kan hebben en wat het niet doet.",excerpt:"Creatine is een van de best onderzochte sportsupplementen. Dit kan het wel en dit kan het niet, zonder marketingpraat.",category:`supplements`,author:l,publishedAt:`2026-08-08`,updatedAt:`2026-08-08`,readingMinutes:5,tags:[`creatine`,`supplements`,`evidence`],published:!0,body:[e("Supplementen zijn het kleinste stukje van de puzzel. Training, voeding en slaap gaan voor. Dat gezegd hebbende: creatine monohydraat is een van de best onderzochte supplementen in de sportvoeding."),o(`what-it-does`,"Wat creatine doet"),e("Creatine vult de voorraad fosfocreatine in je spieren aan, waardoor ze energie kunnen maken voor korte, zware inspanningen zoals zware sets. Op den duur kan dat je helpen iets beter te trainen, en daardoor iets meer spiermassa en kracht op te bouwen."),o(`dosage`,"Gebruikelijke dosis"),e("Een gangbare hoeveelheid is 3 tot 5 g creatine monohydraat per dag, op elk moment van de dag. Een oplaadfase is niet nodig; die vult je spieren alleen sneller."),o(`what-it-wont-do`,"Wat het niet doet"),s("Het vervangt geen regelmatige training of goede voeding.","Het verbrandt geen vet.","De effecten zijn klein."),c("Supplementen zijn geen medicijnen en zijn niet bedoeld om ziektes vast te stellen, te behandelen, te genezen of te voorkomen. Overleg met een zorgprofessional voordat je supplementen gebruikt, zeker als je een aandoening hebt of medicijnen gebruikt."),a("Lees de voedingsgids",`/nutrition`)]},{id:`building-training-consistency`,slug:`building-training-consistency`,title:"Als je motivatie zakt: zo blijf je toch trainen",seoTitle:"Zo blijf je regelmatig trainen als je motivatie zakt",metaDescription:"Praktische manieren om regelmatig te trainen: een minimale training, vooruit plannen, het jezelf makkelijk maken en je voortgang bijhouden.",excerpt:"Motivatie helpt je beginnen; gewoontes houden je bezig. Praktische manieren om trainen iets te maken wat je gewoon doet.",category:`motivation`,author:l,publishedAt:`2026-09-25`,updatedAt:`2026-09-25`,readingMinutes:4,tags:[`motivation`,`habits`,`consistency`],published:!0,body:[e("Iedereen die traint, heeft weleens geen zin. De mensen die het meest vooruitgaan, zijn meestal degenen die op zulke dagen toch komen."),o(`schedule-it`,"Plan trainingen in als afspraken"),e("Bepaal vooraf wanneer je elke week traint. Een vaste tijd en plek betekent dat je niet elke dag hoeft te beslissen."),o(`minimum-session`,"Bepaal een minimale training"),e("Beloof jezelf op zware dagen alleen de warming-up en de eerste oefening. Meestal maak je de training dan toch af. En als dat niet lukt, heb je de gewoonte in elk geval vastgehouden."),o(`track-progress`,"Maak je vooruitgang zichtbaar"),e("Je trainingen bijhouden laat zien hoe ver je al bent. Je getallen zien stijgen motiveert als weinig anders."),o(`get-support`,"Zoek steun"),e("Iemand aan wie je verantwoording aflegt, een trainingsmaatje of een coach, maakt volhouden veel makkelijker. Weten dat iemand naar je week kijkt, is een goede reden om te komen."),a("Plan een gratis kennismaking",`/contact`)]}];var m=class i extends w{published=hn(()=>this.all().filter(t=>t.published).slice().sort((t,r)=>r.publishedAt.localeCompare(t.publishedAt)));featured=hn(()=>this.published().filter(t=>t.featured));constructor(){super(`articles`,y)}bySlug(t){return this.published().find(r=>r.slug===t)}byCategory(t){return this.published().filter(r=>r.category===t)}related(t,r=3){let h=this.published().filter(n=>n.id!==t.id),w=h.filter(n=>n.category===t.category),f=h.filter(n=>n.category!==t.category);return[...w,...f].slice(0,r)}static ɵfac=function(r){return new(r||i)};static ɵprov=te({token:i,factory:i.ɵfac,providedIn:`root`})};export{m as t};